  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (533::BIGINT, 'Al inicio es un profesor que intimida muchísimo. No brinda casi nada de ayuda por lo que usted tiene que ser muy autosuficiente. Hace todos los quices presenciales. Sin embargo, explica la materia muy bien y a partir de Semana 7 sus clases son muy llevaderas y no califica muy duro en comparación.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2026-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'c4c2de1cdc6e7dc5e9f6f50e75d15a1c3b0bda320af637d1a7460eded60d1d51'::TEXT, ARRAY[567]::BIGINT[]),
    (533::BIGINT, 'Es un profesor brillante cuyo conocimiento va mucho más allá de la química, domina muchas áreas y sabe conectar los temas de forma increíble. Su mejor característica es que explica todo a fondo, asegurándose de que entiendas el porqué de las cosas desde la raíz.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2026-06-09T00:00:00+00:00'::TIMESTAMPTZ, '7afc4ecf7237d2eb6e2ad8ae75090cce520d9ae3903adc8383949d975e81a789'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (533::BIGINT, 'Es un profe de verdad, puede que le hable un poco tosco pero es parte de la enseñanza que el da, las explicaciones son increibles y muy claras, si quiere estar relajado no matricule con el, pero si de verdad quiere aprender 100% recomendado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-09T00:00:00+00:00'::TIMESTAMPTZ, '6b8b7ddb2f30a3abffe2a196a9d8fdd961fbba5294608d248bd4aa1ecaac34e5'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'A muchos no les puede gustar porque puede ser o grosero o sarcástico y puede como darte miedo preguntarle algo. Pero sus explicaciones son muy claras y con el tiempo agarra confianza con el grupo y se pasa bien las clases. Sabe mucho de los temas y es muy completo. En consulta es muy buena nota'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-03T00:00:00+00:00'::TIMESTAMPTZ, '5dba6dbe3ca8a6d0d54da4b029826162b6880b128751968cbb3bfa0477f9aba3'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2026-03-17T00:00:00+00:00'::TIMESTAMPTZ, '2a000af04e6ab2abe2b2d033ba6509551c8bb1b1874969fb18a463484c0dc923'::TEXT, ARRAY[567]::BIGINT[]),
    (533::BIGINT, 'Mucha gente habla mal de el pero le soy sincero, si quiere un buen profe de verdad que explica toda la materia de forma super clara lleve con el, porque este profe sabe resumir mucha informacion en poca, y eso hace que se vuelva mucho mas sencillo, de verdad si quiere un buen profe, matricule con el'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Clases excelentes']::TEXT[], '2025-12-14T00:00:00+00:00'::TIMESTAMPTZ, '63b5a3decc83e01cf96c1c4afef197550abd1c56409baca1abf9fc2bda6c9c27'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Muy buen profe, explica súper bien. A veces habla fuerte pero es llevable, muy recomendado. Califica algo suave.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, '0c497345e87051d0ca646decf9592d6a749f1e6becdda7e5dacee9f68ded78ed'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Es un profesor que si usted no le pone a la materia, ni la meta con el, si usted se esfuerza, dele, es el mejor a la hora de explicar, y si ocupa ayuda, vaya a la hora de consulta, y el le va a ayudar y explicar miles de veces, si tiene favoritos y muy claros, y es tosco a la hora de hablar'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'bd701ec4e88aea901106fda87ad3c82bdda73ba8851f94ad9b07d619b7634426'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (533::BIGINT, 'Es una persona muy grosera y suele intimidar a los estudiantes.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2025-07-19T00:00:00+00:00'::TIMESTAMPTZ, '8a73d7383b4555e795a44d67ce338cffc962304aba22422e14bb815d708ef679'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Entre más arrugada la pasa, más dulce es la uva. Esto es completamente cierto con papi. Datos, no opiniones. Al principio es intimidante, pero uno le agarra amor al viejo. Súbanle el sueldo. Debería ser director de escuela.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-19T00:00:00+00:00'::TIMESTAMPTZ, 'd0d63a45c5d8f63753e932fa17afee8d0f11c257f674cc1da6749c279ecf7a4e'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'La verdad al inicio escuché muchas cosas malas de el, pero ya recibiendo su clase es otra cosa. Excelente profe súper pura vida, te ayuda en lo que pueda y explica súper claro. Tiene sentido del humor muy chistoso'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-11T00:00:00+00:00'::TIMESTAMPTZ, '94c173534af9c6d708641526760836fc3cd4f08687171ac406415b340e5baa9e'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Te lo dejare sencillo, si le sientes pánico a la gente medio burlista, no lo matricules con él. Ahora, si no te importa, 100% recomendado, muy bueno explicando y si muestras interés en su clase te ayuda, pone quices cada semana, pero te sirven, y al principio puede ser intimidante, pero es bueno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-07T00:00:00+00:00'::TIMESTAMPTZ, '0401e3db0ba2a4c216bf6facdce29b682c3801478ea90239b3d3c0d5c2520262'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'al principio es complicado "adaptarse" a su manera de ser pero con el tiempo si sos una persona constante que le interesa la clase, que estudia regularmente para los quizzes y que pone atención a lo que dice, la materia no va a ser problema. Los exámenes de la cátedra se te van a hacer muy fáciles.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'bb569f93a511626146ccd29d915f901acfad42dadeb8cc7a9026788bd395363b'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Un profesor que mucha gente odia por su manera de actuar, pero en lo personal me encanta su forma de ser, si te sabes llevar bien con él sus clases son muy buenas y explica excelente. Recomiendo ir a consulta y estudiar al día ya que sus exámenes cortos pueden ser duros.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'af822b7771ea7a12c3cb6757eb0c734d2ecf7763234c483d0b56c17f0c6a5f67'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Al principio se muestra duro pero cada vez hace más chistes y crea un ambiente bonito en la clase. Explica muy bien y lo ayuda a uno, los quices son un poco duros.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'bdd6b7be70843d035ca20dc179385b0cb1ffd1a564f0a1e576c26bdc1df2aa39'::TEXT, ARRAY[567]::BIGINT[]),
    (533::BIGINT, 'Al inicio es grosero, pero luego vacila mucho. Intenta ayudar lo más posible y se preocupa por los estudiantes, no le interesa quedar a nadie. Muestre interés y MUY MUY importante que vaya a consulta, así el le ayuda. Los quices un poco difíciles y las clases cortas, en consulta es un amor.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'f692f1a14e0e90f5dbaccbbd858128d6de40a7604507c4cd83466bdc0a4decdd'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'No matricule con él, le encanta humillar a los estudiantes por hacer simples errores, sé nota que da la clase por dar. Además, se enoja si ud comete un simple error y hará lo posible para hacerte quedar mal. Encima no explica bien, y piensa que uno nace sabiendo todo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-04-05T00:00:00+00:00'::TIMESTAMPTZ, 'ef30aa9b3ec95c59d794fc278ab3480c12d06fed9768c36e078bf184b5ea289a'::TEXT, ARRAY[567]::BIGINT[]),
    (533::BIGINT, 'Es buen profesor, hace bastantes exámenes cortos y hay que ir preparado. Con los exámenes de cátedra nos iba bien, pero también fue insistente en que no dejáramos el curso, y fue muy motivador'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-18T00:00:00+00:00'::TIMESTAMPTZ, 'face06818d0d695f88c4eadb52edb3c4c66b0dd4a94fcc2a13beac4f41cc01eb'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (533::BIGINT, 'El profe al principio es muy tosco, pero con el pasar del semestre va agarrando confianza con el grupo, si no entiende pregunte sin miedo, no se tome personal lo que le diga y si ve que le puso prácticamente lo ayuda a pasar'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2023-12-13T00:00:00+00:00'::TIMESTAMPTZ, '8255a50e106fa8ada2863bd58fd529ba9b1828c5d37f0356e2487f7e50274258'::TEXT, ARRAY[614]::BIGINT[]),
    (533::BIGINT, 'Las únicas personas que dicen que es mal profe son las que no le ponen mucho interés al curso y solo dan lo mínimo. Es un excelente profesor, con bastante carácter lo cual a personas muy delicadas es la razón que les desagrada pero es bastante ameno y divertido cuando lo conocen bien, recomendado'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-05T00:00:00+00:00'::TIMESTAMPTZ, '462737393c730e4205c98070e846681c3799f6f37b02b35b56edaf0d32a57953'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (533::BIGINT, 'El profesor en un inicio puede parecer muy rudo y grosero, pero es solo de no tomarlo personal, trata de poner a pensar a los estudiantes. Las clases son directas al tema, explica demasiado bien, pero pregunte cada vez que lo necesite (si él ve que se interesa en el curso le va ayudar demasiado).'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Clases excelentes']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'cc9f593a64a9014f2bafc9f11f07e3133635f439e0b44d88bf5548ef7ceb1c0d'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'El profe puede ser muy rudo a la hora de hablar y da un poco de miedo, pero en realidad enseña muy bien, tiene buen carácter y es justo al calificar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-20T00:00:00+00:00'::TIMESTAMPTZ, '4f506654e81f02e736a2bd29538b3b197016e677ef814749f0eb20f82ed8be9e'::TEXT, ARRAY[614]::BIGINT[]),
    (533::BIGINT, 'Increíble profe y persona, tiene que saber que el profe es muy concho y probablemente lo regañe mucho, pero le gusta dar retroalimentación, es muy gracioso y trata de hacer las clases mas amenas'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2023-10-31T00:00:00+00:00'::TIMESTAMPTZ, '5fb7d1d8d8981e77d5a3c6692c947271413658bb8af983232afd538330bb6bb8'::TEXT, ARRAY[614]::BIGINT[]),
    (533::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2023-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'd71ca4b88cb55f8e78e41fefe00168a85d0a10d5d9ce9aafd7b39c65f382113b'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Un profe muy pura vida, vacilón, muy directo para hablar pero no hay que tomárselo personal...muchos exámenes cortos pero califica los convenientes para el estudiante, las clases son al grano y apunte todo lo que escriba en la pizarra y todo lo que diga en clase porque no usa presentaciones.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'ad4dd7ec614736321e18974f9079a398a9dcf7424b6697c2703fce41a4f21ebf'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (533::BIGINT, 'El profesor tiene mucho conocimiento y hace ejemplos para que los estudiantes entiendan el tema ,suele molestar y presionar cuando se le pregunta ,solo no hay que tomárselo personal y tener paciencia , Aparte de eso es buen profe.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '1981411aa892679f6ea6477ffafe57a60f94e721f206b57f56d0770ddf574433'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Es un excelente profesor, se nota que sabe de la materia y explica súper bien, anota en la pizarra justo lo necesario, hace quices fáciles (si se estudia de antemano y en comparación con otros profes). 100% recomendado.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, '85d93a9c4ced02fccfcee9ce692bb65c436ccee84d5d89b1193820346a0f2152'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Hace muchos quices y muy duros, es un poco arrogante, si le cuesta química no se lo recomiendo, pero si le faltan unos puntos si se los da.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'd3ecd36c99cb05803c020bd3baaafeec0efe5633df86a09eb1fd19f7382993ed'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'el profe sabe mucho de muchísimos temas. Intenta hacer la clase entretenida. Si es importante repasar la materia y prepararse para los quices semanales. Este semestre hizo repasos antes de los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'aaa1c9b030666f913148f2d9940024343255cd9d78e750e374de405d9e61c8ef'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Es super inteligente y conoce de todo lo que habla, se esfuerza para que todos entiendan y si usted pone de su parte, él le responde de buena manera. Puede parecer grosero al principio, pero con el tiempo se vuelve super buena gente y comprensivo si lo amerita.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2023-05-27T00:00:00+00:00'::TIMESTAMPTZ, 'b03a3d63625d0eb4f6103e1919e4dcb9207f5b52a94361a312be858cb04de14e'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (533::BIGINT, 'Sus clases son muy entretenidas, si usted no entiende algo el mae va a intentar de cualquier manera que usted entienda, los primeros días podrá parecer amargado o arrogante,, luego se le entiende su sentido de humor, se preocupa porque los estudiantes pasen.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2023-05-17T00:00:00+00:00'::TIMESTAMPTZ, 'c8b2ca904b7484394736a6da4922b64c16b1eeb64b397a585c9fef4fb2df3119'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'El profe es muy buena persona pero si no sabe química ni se le ocurra matricular con el, explica un tema en la clase y no lo vuelve a ver, y siempre se atrasa con la catedra entonces para los exámenes es muy mal trata muy mal a los estudiantes, algo que si tiene bueno es que hace muchos quices.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes']::TEXT[], '2023-04-25T00:00:00+00:00'::TIMESTAMPTZ, '5e1fdb508b84dc88370678ba1e2661c0666aea9aaf2943578f61b15f7ffe8bf3'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2023-04-18T00:00:00+00:00'::TIMESTAMPTZ, '7fcf5892b94f4758759cf263e24cf2231795b827138f4260e73edf11a18e260e'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'El profe es una excelente persona, carismático y enseña para la vida. Pero para los exámenes hay temas que explica por encima o casi nada, por lo que si no estudia por su propia cuenta le va a ir feo en los parciales. Los quices los hizo al puro final del curso, si le falta 1 punto el ayuda con eso.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Pocos exámenes', 'Exámenes retadores']::TEXT[], '2022-12-13T00:00:00+00:00'::TIMESTAMPTZ, '6d93ef268cc3e77cfc3c42f46cd72ae75fc9b3fc821cebc8ae3c502fa7649b7a'::TEXT, ARRAY[614]::BIGINT[]),
    (533::BIGINT, 'Si no sabe mucho de química no matricule con él, las clases son entretenidas pero no enseña de forma útil para los eámenes, sale mejor estudiar por cuenta propia que llevar una clase con él'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-30T00:00:00+00:00'::TIMESTAMPTZ, '778e56bdbeb13e124106a3c40d4104c7a432e17442184e8a9cec50d89c722627'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (533::BIGINT, 'Es un profe que puede parecer intimidante, pero si uno pone atención y hace preguntas él hace lo posible para que el estudiante pase y que entienda la química en sí'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Da crédito extra']::TEXT[], '2022-11-24T00:00:00+00:00'::TIMESTAMPTZ, '7fa9cdfbad73834b70b32d0c2cc540f22313166115c0b89a304f018d69ad6b46'::TEXT, ARRAY[614]::BIGINT[]),
    (533::BIGINT, 'El profesor es una teja, uno se ríe mucho en sus clases, en virtualidad era otra vara, pero presencial me gusto mucho, de igual forma si hay que estar al día con la materia porque a veces se atrasa referente a catedra'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2022-10-21T00:00:00+00:00'::TIMESTAMPTZ, '99858a818d95264ab7c72f694ee1af2f0688623043ed4c6725b0f774a39c3bc2'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Sus clases son bastante confusas y, en general, el profesor es muy desorganizado con la clase.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'fc2006a6284b82822083bba27451d952a8344dcadc986bb9b605250d7739a92e'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (533::BIGINT, 'Si saben algo de química puede que les guste el profe, pero si llegaron como yo super principiante entonces mejor no matriculen con él... No enseña nada de lo que viene en los examenes y no ayuda mucho'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'a322b90cbe119007ac148f8572ce06dd6f55e04843e15f3427a627d5c738e076'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Hace clases de menos de una hora y no explica tan mal pero es muy concho con los estudiantes y si le pides ayuda el no explica muy bien. Poner mucha atención a la clase porque a veces avisa de quices solo una vez. Da tiempo para entregar los trabajos/quices.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'f3295e664bff9fcabad7b05b5128f957ed94c910c2a557b486c2c4eba1208382'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Si tienen buenas bases de química entonces tal ves no se les complique mucho las clases, pero si no este profe los va a confundir un montón. De verdad solo se lo recomendaría a gente que recibió muy buena química en el cole. Odia repetir explicaciones entonces pónganle atención.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-18T00:00:00+00:00'::TIMESTAMPTZ, '567699ba932a740303208e070e9ed7da6ffeb8b961f62177ec1a3c4b28de4ff5'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (533::BIGINT, 'Al principio puede parecer enojón, pero es un excelente profe y es pura vida.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-12T00:00:00+00:00'::TIMESTAMPTZ, 'c4d02b137ac34f2fc06d78199f3141bd62ce03ea20918bcaa6e81cf523eded2d'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (533::BIGINT, 'El profe se nota que sabe mucho. Aunque se le vea un poco prepotente, siempre ayuda cuando se le necesita. Tal vez no logre explicar la materia de la mejor manera.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2022-01-15T00:00:00+00:00'::TIMESTAMPTZ, '8e3d94d9b821b17fb3a020cf634f1b9fa2b942369d09c5665bf44caaaa9e1be7'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (533::BIGINT, 'El profe sabe muchísimo de la materia y se nota en las explicaciones de las clases. Las clases no son largas y siempre las graba, la asistencia no es obligatoria pero recomiendo asistir. El profe puede parecer prepotente pero ayuda al estudiante bastante en las evaluaciones. Lo recomiendo bastante'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-12-12T00:00:00+00:00'::TIMESTAMPTZ, '7c01ce48da7cc8c7e14a3eb51473c981950666637bd6f16f14a5789d41a142f0'::TEXT, ARRAY[3168]::BIGINT[]),
    (533::BIGINT, 'CALIDAD de profesor!! Es muy dedicado al curso, explica detalladamente todo y está siempre atento a consultas de los estudiantes. Las prácticas, pruebas y consejos le ayudan enormemente para los exámenes. Si quiere llevar química y aprender bien, no dude en matricular con él!! 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-11-24T00:00:00+00:00'::TIMESTAMPTZ, '77ab428fd25094bf0101e9942c8f835850b405c11eac9b03a1f49c8cab84707a'::TEXT, ARRAY[614]::BIGINT[]),
    (533::BIGINT, 'En virtual este profe logro adaptarse de la mejor forma posible, las clases fueron muy especificas, explicaba claramente, calificaciones claras, si mi carrera tuviera que llevar más quimica, sin duda buscaría llevarla con el'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Muchos exámenes', 'Clases excelentes']::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'e103b4e7d4f88e0524d1ab7497a567e044001fcf890a776a5d34332caa608a62'::TEXT, ARRAY[614]::BIGINT[]),
    (533::BIGINT, '(Virtual) Muy buen profe, explica excelente. Clases cortas. Hace muchos ejercicios para que los estudiantes entiendan y siempre que uno tenga dudas se puede hablar con él. Tiene una forma un poco dura de hablar con los estudiantes, pero si a usted no le importa le recomiendo matricular con él 10/10.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2021-11-08T00:00:00+00:00'::TIMESTAMPTZ, '0d4a31ec360eb84133132a05cad282835ebd817ad77f783123cc458ad7357a39'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, '10 de 10, excelente profe, si quiere pasar quimica básica con todo claro, este es su profe, eso si, si no le gusta que le hablen duro, ni se atreva luego a estar llorando'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2021-11-08T00:00:00+00:00'::TIMESTAMPTZ, '4d4e815bb2dfb130221bea7c884c8cc3399e02c2229d20813a9757335442ade6'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'El profe es muy prepotente y si preguntas te hace ver como un estúpido y te humilla, no explica mal pero aveces usa lenguaje muy técnico, hace muchos quices fáciles para que el estudiante pueda tener mejor nota si quiere pasar el curso fácil y no aprender mucho llévelo con el'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes']::TEXT[], '2021-07-26T00:00:00+00:00'::TIMESTAMPTZ, '46ff001e1614f26f7dd782d6f2e15f303984a382d59ab43bbe194fce89beaf60'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'El mae en si es bueno se la come entera, pero su carácter, pedante y egocéntrico es pésimo y ni quiera Jesucristo le haga una pregunta porque de un solo le sale con otras varas y lo deja como un culo JAJAJA evítelo mejor, si le cuadra que lo dejen como un culo JAJAJAJA #MANDESEDURO.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '4979d50a7ee6cccb9d2acf0d8f108a564ab590d47e5afd7451897c25a62ab63e'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (533::BIGINT, 'El profe conoce mucho de su área pero explica todo en lenguaje muy técnico, hace muchos exámenes cortos pero son fáciles y no responde dudas de buena manera. Sus clases son muy cortas.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '95af7d618c1b930c08eefb0fa717c30da57ed0c5b8538dfac06de6d0fc30e820'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Salga corriendo. No sé cómo habrá sido el tipo en presencial, pero en virtual es un dolor, las clases super aburridas, y ni se le ocurra preguntar algo que no entiende si no quiere salir con la humillada del día. El mae se nota que sabe mucho de su área, pero para enseñar no sirve, es muy prepotente'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-12T00:00:00+00:00'::TIMESTAMPTZ, '76edc55f85f7bac90a6fe03613535b9d6e8557e9c6acc344cb78540b065c526c'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Es muy serio e intimidante, lo que no genera motivación para las clases. Hace clases cortas pero explica muy rápido y usa lenguaje muy técnico; cree que toda la gente es experta en la materia y es arrogante. Hace quices todas las semanas.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-07-12T00:00:00+00:00'::TIMESTAMPTZ, 'b9c627c01aaa2fc8989bd806395dedf5795c731977e2282c70422e301f62f3e9'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Pocos exámenes']::TEXT[], '2021-05-22T00:00:00+00:00'::TIMESTAMPTZ, 'f7b5c51d569bc29de123f748092b2c7420fedc0cacb5333c19c8e97c7fe440ef'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (533::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-05-13T00:00:00+00:00'::TIMESTAMPTZ, '3574d38348f6906e2808e861e9d38dc73949d5dd4000d609d09133b6d8da39f3'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, '(VIRTUAL!!) Es un curso bastante pesado, no es imposible pero lleve la materia la día, clases de menos de 1h. Hay que leer demasiado, la mayoría es inglés. Hace bastantes evaluaciones, algunas bastante complejas. El profe es medio intimidante pero está dispuesto a ayudar para que uno entienda.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, 'c6cc8dfe6476d60d26386ac564acfb1fa92b25faa48e9371681a1d850cb15640'::TEXT, ARRAY[3168]::BIGINT[]),
    (533::BIGINT, 'Una clase fuerte pero si le pone se pasa súper bien. Uno aprende un montón y aun más si se aprovechan las consultas. El profe es serio,pero si usted le pone interés al curso se hace mucho más ameno. En virtual ojo con las comprensiones de lectura que tienen bastante %, vaya a consulta a comentarlas!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'c2e572f2949788ed588b416ede65060a06580e58cf4945b8cedb797642d34494'::TEXT, ARRAY[3168, 3166]::BIGINT[]),
    (533::BIGINT, 'Sinceramente tenia miedo al principio por los comentarios pero mientras usted se esfuerce la logra y más virtual. Los quices son muy fáciles. A veces esta de mal humor, pero siempre contesta dudas o consultas y lo hace en el menor tiempo posible. Es un profe que le interesa que usted aprenda.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '42d823278f93662edb96b3c651f4477d7fd7ebf3791a873c399ee51eec55ed3b'::TEXT, ARRAY[614]::BIGINT[]),
    (533::BIGINT, 'Calleja es el mejor profe que he tenido en el tec, el mae disque juega de vivo pero es una teja y solo adora joder que hace la clase más divertida, y se preocupa muchísimo porque uno aprenda no solo de química sino de la vida'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'b3cc1e8e9700941e6e98feffa26e43e349c45f3ad988073cfc1f9b3311036f19'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Muy prepotente, humillador, en lo personal de los peores profes que he tenido, si tiene dudas no demuestre miedo porque casi ni le explica.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'fe2f6256fe44f49a28eaae57f9c35dd1b83ffb41809e3ee68882689f564026b8'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (533::BIGINT, 'De los mejores profesores que tiene la escuela. Al inicio asusta pero en realidad es super buena gente y ayuda un montón en el curso, nos dió muchas oportunidades para ganar puntos extra. No falte a clases, sea puntual y participe en clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-12-03T00:00:00+00:00'::TIMESTAMPTZ, '5ed7c59ab2e14b51577fe0bab670932dca08dfdae1816f74ad1ba9ee42f291bd'::TEXT, ARRAY[3168]::BIGINT[]),
    (533::BIGINT, 'Gente, Calleja es un crack! Este profe no sólo enseña química, enseña sobre la vida. Sí... se le puede cagar o algo así, pero por cosas que son válidas y uno como estudiante no ve... demuestre interés, y no le haga creer que él no sabe, el mae sabe todo jaja'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, '580a236e02acd20378a1cc2af536affde970aec2edfb4578d789ceb1d1cb64a0'::TEXT, ARRAY[2814]::BIGINT[]),
    (533::BIGINT, 'Calleja tiene un carácter fuerte y si piensa llegar a esa clase a vacilar, él se le caga, pero es un profesor excelente, sabe demasiado y para explicar es muy bueno. Hace bastantes quizes y eso ayuda un montón para que uno esté al día con a materia. Califica justo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-07-09T00:00:00+00:00'::TIMESTAMPTZ, '9e4e09762deb517d34e5ef0dbe8cdb49e797a5d22b8116bab781a1992340a2ef'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Excelente profesor, muy serio y se nota que sabe demasiado, su actitud es aveces un poco negativa, pero en general es excelente.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2019-06-28T00:00:00+00:00'::TIMESTAMPTZ, '42eb6893352ea687276165200ed19a92e5cea9888ac2ed3114c3939847a1438b'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Al principio es todo serio, ya después es demasiado buena nota. Hay que estudiar mucho en la casa para llegar a aclarar dudas en la clase. Es demasiado crack y hace bromas en la clase. No pregunté cosas estúpidas o no se haga el sabelotodo porque literal se le caga.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'La participación importa', 'Brinda apoyo']::TEXT[], '2019-06-26T00:00:00+00:00'::TIMESTAMPTZ, '390d2e9da901a80f1d6ae29bdd78ed0c43118e9a024f9af1762864502ad42253'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '4e918c5632634d8d53a5ea48f98e78faf4c3efe268d45f06da0138febb6b0af0'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'EL MAE SE TIENE SU CARACTER PERO ES UNA TEJA, BRINDA AYUDA LO CUAL ES GENIAL, VAYAN A CONSULTA CON EL, ES LO MEJOR...AL PRINCIPIO LA GENTE MEDIOCRE SE QUEJA DE EL PERO HAY QUE APRENDER A SER AUTODIDACTA. PARA MI EL MEJOR PROFE DE LA ESCUELA DE QUIMICA'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '2ed124115c20123a648d98f734dd7153fa0e7412aa8808bb88be452107e9b2b7'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Se debe ser algo autodidacta,no es mal profe.Sabe demasiado sobre Química y si usted muestra interés en la clase le va ayudar y explicar las veces que sean necesarias.Los repasos que da para el último exámen ayudan un montón.No siempre avisa si hay quiz.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '9d8c7b69c71d4402622c074be5df277683549a1c54a55bdace421664c2c06776'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'El mae es bastate serio y profesional, pero si usted pone de su parte para aprender el mae lo ayuda, y sus consultas son demasiado buenas, si usted es un mediocre ni se le ocurra matricular con el, si sí le pone lo pasa muy fácil.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Da crédito extra']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'aad217d048dd493739a3275bf4b97a55ee76bf3a1b92c0d5e35f9fb0c7c16111'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'e12529e9189a0dda468db9a949ac9853d9e556b72aeced299f7d4bb358fabf68'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (533::BIGINT, 'es muy buen profesional, experto en la materia, tiene un carácter fuerte que puede influir en el aprendizaje, se necesita ser autodidacta para pasar con él.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-28T00:00:00+00:00'::TIMESTAMPTZ, '5bb66d476794932e710992bfc83ca8ab5ad901e1aa9c38cee38e9e1b5eaebafa'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (533::BIGINT, 'Una vibra este mae. Tiene un carácter peculiar que a la gente mediocre le choca, pero el mae hace su brete, y conoce la materia demasiado bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2019-05-17T00:00:00+00:00'::TIMESTAMPTZ, '44cbd460bd76962f70543f88dd282d959b212768e1983d95eafd7dc9e117d8cf'::TEXT, ARRAY[567, 613]::BIGINT[]),
    (533::BIGINT, 'Mal profesor, si tiene buenas bases de química general pasa sin problema, de lo contrario debe ser autodidacta'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-03-03T00:00:00+00:00'::TIMESTAMPTZ, '09cd8b6556c8fce0710a231551523e566358c05d1f2ef4a84de8e17231d9379c'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'El mae es arrogante y le encanta hacer parecer a todo el mundo que es un idiota, parece ser un buen profesional pero como profesor no sirve'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'f8ae8672b94f621979c19997148dedcd0e6c66bfeed9216ebb33cffaac78364b'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Califica justo. Si usted le cae bien, es buena gente, si no, todo lo contrario. A veces es un poco desordenado y poco claro.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-20T00:00:00+00:00'::TIMESTAMPTZ, 'ee770be5de44f432c197dee8a6f158c9fe2b3766a8534d6914651d613c9a6031'::TEXT, ARRAY[2814]::BIGINT[]),
    (533::BIGINT, 'Excelente profesor, experto en la materia. Tiene un carácter muy fuerte, por eso muchos tienden a quejarse de él, pero si uno muestra interés y le pone el ayuda muchísimo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2019-01-04T00:00:00+00:00'::TIMESTAMPTZ, 'd09dffd9490049c92b8b8eb844cf143e9bcf09d70edc8998a911a7d799fc90a9'::TEXT, ARRAY[2814]::BIGINT[]),
    (533::BIGINT, 'Siempre sabe de lo que habla, explica muy bien y con muchos ejemplos. Es un poco serio y parece andar siempre enojado, pero no es así. Super claro a la hora de dar la materia'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Clases excelentes']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '206435ddec527f385e4b5d0aa603cf1566e32a7ba39dfb41cd78960c6b67eb61'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'El profe explica muy bien, y sabe siempre de lo que está hablando, solamente que da mucho miedo, tome notas de lo que explica, tenga cuidado con lo que pregunta porque puede que lo humille muy feo. Además todos los quices son sorpresa y súper duros.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '533c8ef76f595c80140edd2939364461e6c803de7c79d8863ef707c9906a2517'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'PÉSIMO! Persona orgullosa y bipolar, no acepta un error aunque el estudiante tenga razón, inclusive respaldado por otro profesor. Te humilla y el 90% del tiempo anda de malas. Lo evitaría para cualquier curso, califica duro e injustamente, y si le reclamas algo mal calificado se enoja y te grita.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'c359392c1758bce882a59cd100173ea23bbaa537be8275efd8c7e1f3572fd574'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Clases muy aburridas, un poco arrogante. A la hora de preguntarle algo lo humilla a uno y si por milagro lo quiere ayudar no logra resolverle la duda. No explica bien.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'a2e1549c38926d590d8d3054cbd802316b50cf13c9debe6e9adc05f64a1e14b0'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Busque OTRO profe!!!! Aveces es un excelente profe, pero cuando se le mete el agua (casi siempre) es muy malo y aburrido'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'dc1c9d92248f71772abc5b5878ffce1dd3205e620ab6976b346a730a1c248c2b'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'El profe no es malo, realmente sabe mucho y utiliza muchos ejemplos para relacionar la materia. Los quices son difíciles, no da la tabla periódica. Se burla de los estudiantes si la duda es muy tonta, pero eso depende mucho también del estudiante, no con todos es así. No es malo, pero hay mejores.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'c3ac0c8c4187554d107d3690fe5ffc5c158ddd1d5ec12f613d368708758b94e0'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Asistencia obligatoria']::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'ca1fef7d5a9e99ff9cd568d4e0f7b29f358bb8fe1ffb366e6e163b2f9a34ad99'::TEXT, ARRAY[4253]::BIGINT[]),
    (533::BIGINT, 'Hace quices sorpresa'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'e7c387732fedfa87fec5f5bde200194e9d26e5827686d51afcb6ba53a248d694'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'los quiz son sorpresa y además muy difíciles, le gusta llevarle la contraria a lo establecido en el curso, nunca mas llevaría un curso con él'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '17e39aea7c0d95747065932ff78d01bff4c00a2101898ab007fc65701a182a9e'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'PÉSIMO! Hace quices sorpresa difíciles en los que no dan ni la tabla periódica, usa mucho el libro de Brown, se burla de uno en la cara, no crea ningún ambiente de confianza en el aula, no reconoce sus errores, orgulloso hasta morir deberia ser su apellido.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'd798738891b4fb93853a91c4c3c1e36166dde1e31038e3ee9a4a9be84eb2bf2c'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'mejor matricule con cualquier otra persona'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-06-08T00:00:00+00:00'::TIMESTAMPTZ, '15c6d24d6857ecd23f12e0ca766f41e7d9f905e50b049a19b5f374abb2cce44f'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores', 'Muchos exámenes']::TEXT[], '2018-05-09T00:00:00+00:00'::TIMESTAMPTZ, '39814c41f0e80530965fae9fcfb1ea67d40d0ef3101c209e5f6d386f26bb7304'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'b46e06ae07e81713903cafda92006281c9e02858ede221e03cd6aa4113f03181'::TEXT, ARRAY[3168]::BIGINT[]),
    (533::BIGINT, 'Al principio de semestre es un infeliz, por todo regaña, a veces se burla y demasiado sarcástico, cae muy mal, pero al final ayuda mucho, no le interesa que se quede nadie. Es muy irresponsable con la entrega de informes y examenes y hace quices muy dificiles. Regala muchos puntos.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '651e160ee4095ed7081d75289e709e7ec20a2ace9ef2ea85bee9981f9decb8be'::TEXT, ARRAY[613]::BIGINT[]),
    (533::BIGINT, 'Pésimo, es una de las personas más desordenadas e irresponsables. La evaluación del curso se la sacó de la manga al final del semestre porque nunca nos la entregó. NO matriculen nada con él'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '2d37d3a2b3671778c51bd8f474cbff880e64ec38b61e1964d655e0a072619707'::TEXT, ARRAY[2814]::BIGINT[]),
    (533::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Inspirador']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '4b6253b530590a2c7bda33db4e12cc343b559010dcafae3fcab06657ddc6f5d9'::TEXT, ARRAY[3168]::BIGINT[]),
    (533::BIGINT, 'Si se le pregunta algo explica bien pero algunas veces se burla, quices muy dificiles'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'fbed30b5f33a448b8dd3e9e05e6d5e4c9a661b2c370b2520da45f0baf82c49e0'::TEXT, ARRAY[567]::BIGINT[]),
    (533::BIGINT, 'Quices difíciles, no explica muy bien, pero es buena gente (en algunas ocasiones)'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-06-03T00:00:00+00:00'::TIMESTAMPTZ, '568183926607af42a9d7c5b599836d0ee65bd46be0da2cef48ee3384a023a88a'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Pasé con buena nota el curso, pero fue gracias a las buenas bases que ya tenía antes. Es un pésimo profesor. No lo considero tampoco una persona muy estable puesto que, a veces te va a aclarar dudas con paciencia y a veces se va a burlar de vos.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, '27e565c853570b8607b85396ada3a4c90b26e90073b4a25aa4d76b7256c17f66'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'califica normal, mal humor y quices muy dificiles'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '83ebf1d6b1a85ecbddde8175e10987d324c291dda1715d43e57d102466924f6e'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Es un profesor odioso. No enseña nada.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-13T00:00:00+00:00'::TIMESTAMPTZ, '4a14a6d996dad8ac90e49041d4857920db3922ccb3162e651b0247dee11129f4'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Si usted desea una clase donde se sienta cómodo, no matricule con él. Siempre da explicaciones larguísimas y se termina perdiendo en lo que decía. Si uno se acerca a él con una duda, a veces es odioso y lo "vacila" con algún otro estudiante, a veces es muy buena nota y te ayuda. NO MATRICULE CON ÉL.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '5528b55c736c075e7ce87b05551ac69f5896f2e0bbaa7f823593ac87a717815b'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Es un profe bueno hasta que la clase lo haga enojar, es bastante paternal y se preocupa por los estudiantes a menos que ellos hagan algo que no le gusta, desde ese momento se vuelve muy malo, pero mientras no hagan nada problemático todo bien ;)'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'f60b4633c53c3bad5968bdeda99fb07d5152a59e9ff55ee812386c29b8ff4539'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '08123ec927b6c1e79c8e7c8a99d01aac7bd9ca7e916d3ae966b56d4b03611a77'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Excelente como persona, excelente como químico, pésimo enseñando. No sé por qué pero no da materia que califican en los exámenes de cátedra'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'bb6cc05b43ecdb103ed3ddc274397005670df4aca399bbf370b3ff6868d23037'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (533::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '7efe3a2bc7473194a90a8b4a1d2b062ddfd061ed9080e52640f661da484d7e68'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Clases largas']::TEXT[], '2016-06-04T00:00:00+00:00'::TIMESTAMPTZ, '8c015058f960bb4107f4f02b1f26d2ec6298b55aba425b7cdc039aca9e4de1c8'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Sin comentarios, un insulto a la pedagogía.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-23T00:00:00+00:00'::TIMESTAMPTZ, '19ff046e7b469b294281c5e3bd9b1f77c9bc70c2d2c0dc629d195dbb744592a8'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Se pasa... pero si quiere aprender de verdad, busque otro.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-08T00:00:00+00:00'::TIMESTAMPTZ, '899ff40554005fd244d55c72c42f20fea2cac852d11b896865f3604c85460b41'::TEXT, ARRAY[568]::BIGINT[]),
    (533::BIGINT, 'Buen profesor, no se sabe cuando esta enojado o feliz y eso puede intimidar un poco durante las clases/exposiciones/exámenes. Si se aprende bastante y atiende dudas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-22T00:00:00+00:00'::TIMESTAMPTZ, '0ef5bc5e59135d759009574de573aa10c32afb95d51b6c9187516ff441a8c027'::TEXT, ARRAY[2814]::BIGINT[]),
    (533::BIGINT, 'Da muchos ejemplos en clase y mantiene la clase entretenida. Explica muy claro'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, '2bc6acae0a7411f2d1af9c4b60891a50523cc89adce38320bef7414ebddf9cdc'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (533::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-03T00:00:00+00:00'::TIMESTAMPTZ, '37d49056dbb5ffa97f53116e913708ca9d9dafa2b3c7c8c807a0c0e4c368e7c8'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (533::BIGINT, 'Los quices son durillos, pero nada del otro mundo. Se nota que sabe lo que está explicando y da puntos por el reciclaje.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, '001b901db8bd551993c915fe6253daf05333e2d2310a17f80cf1924366b0fa1a'::TEXT, ARRAY[567]::BIGINT[]),
    (533::BIGINT, 'Es excelente si le caes bien y si demuestras interes por el curso te ayuda,incluso da puntos. En los quices si debes estudiar pero al final hace otros para puntos extra, en informes no califica tan duro, y en examenes de igual forma no califica rudo. La mayoria de veces es muy serio.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-26T00:00:00+00:00'::TIMESTAMPTZ, '0937abd8d31c01e578c9e7e7a6062567ffebd101db1999e015d36499e171cc57'::TEXT, ARRAY[567]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
